    },
    {
      "decision": "objective_sense",
      "evidence": "\"minimize the total completion time, known as the makespan\"",
      "options": [
        "minimize Cmax",
        "maximize Cmax"
      ],
      "plausibility": [
        0.99,
        0.01
      ],
      "majority_option": "minimize Cmax"
    }
  ]
